,p_static_id=>unistr('resultado-de-b\00FAsqueda')
,p_title=>unistr('Resultado de b\00FAsqueda')
,p_template=>4075786578761660127
,p_display_sequence=>40
,p_region_template_options=>'#DEFAULT#:t-Region--scrollBody'
,p_component_template_options=>'#DEFAULT#:t-Report--altRowsDefault:t-Report--rowHighlight'
,p_source_type=>'NATIVE_SQL_REPORT'
,p_query_type=>'SQL'
,p_source=>wwv_flow_string.join(wwv_flow_t_varchar2(
'SELECT v.id_viaje,',
'       v.fecha_hora_salida,',
'       v.punto_origen,',
'       v.ruta_general,',
'       v.costo,',
'       v.cupos_disponibles_viaje,',
'       e.nombre || '' '' || e.apellido AS conductor,',
'       ve.marca, ve.modelo, ve.color, ve.placa,',
'       LISTAGG(p.parada, '', '') WITHIN GROUP (ORDER BY p.parada) AS paradas',
'  FROM viaje v',
'  JOIN conductor c    ON c.documento_id = v.id_conductor',
'  JOIN estudiantes e  ON e.documento_id = c.documento_id',
'  JOIN vehiculo ve    ON ve.placa = v.placa',
'  JOIN viaje_parada vp ON vp.id_viaje = v.id_viaje',
'  JOIN parada p       ON p.id_parada = vp.id_parada',
' WHERE LOWER(v.estado) = ''programado''',
'   AND v.cupos_disponibles_viaje > 0',
'   AND (:P2_FECHA IS NULL',
'        OR TRUNC(v.fecha_hora_salida) = TO_DATE(:P2_FECHA, ''DD-MM-YYYY''))',
'   AND (:P2_ZONA IS NULL',
'        OR v.id_viaje IN (SELECT id_viaje FROM viaje_parada',
'                           WHERE id_parada = :P2_ZONA))',
' GROUP BY v.id_viaje, v.fecha_hora_salida, v.punto_origen, v.ruta_general,',
'          v.costo, v.cupos_disponibles_viaje,',
'          e.nombre, e.apellido, ve.marca, ve.modelo, ve.color, ve.placa',
' ORDER BY v.fecha_hora_salida;'))
,p_ajax_enabled=>'Y'
,p_ajax_items_to_submit=>'P2_FECHA, P2_ZONA'
,p_lazy_loading=>false
