wwv_flow_imp_page.create_page_process(
 p_id=>wwv_flow_imp.id(7876182015316695439)
,p_process_sequence=>10
,p_process_point=>'BEFORE_HEADER'
,p_process_type=>'NATIVE_PLSQL'
,p_process_name=>'Aceptar solicitud'
,p_static_id=>'aceptar-solicitud'
,p_process_sql_clob=>wwv_flow_string.join(wwv_flow_t_varchar2(
'DECLARE',
'  v_viaje solicitud.id_viaje%TYPE;',
'  v_cupos viaje.cupos_disponibles_viaje%TYPE;',
'BEGIN',
'  SELECT s.id_viaje',
'    INTO v_viaje',
'    FROM solicitud s',
'    JOIN viaje v ON v.id_viaje = s.id_viaje',
'   WHERE s.id_solicitud = :P9_ID_SOL',
'     AND v.id_conductor = :APP_USER',
'     AND UPPER(s.estado_solicitud) = ''PENDIENTE'';',
'',
'  SELECT cupos_disponibles_viaje',
'    INTO v_cupos',
'    FROM viaje',
'   WHERE id_viaje = v_viaje',
'     AND UPPER(estado) = ''PROGRAMADO''',
'     FOR UPDATE;',
'',
'  IF v_cupos <= 0 THEN',
'    RAISE_APPLICATION_ERROR(-20001, ''El viaje no tiene cupos disponibles'');',
'  END IF;',
'',
'  UPDATE solicitud SET estado_solicitud = ''ACEPTADA''',
'   WHERE id_solicitud = :P9_ID_SOL;',
'',
'  UPDATE viaje SET cupos_disponibles_viaje = cupos_disponibles_viaje - 1',
'   WHERE id_viaje = v_viaje;',
'',
'  apex_application.g_print_success_message := ''Solicitud aceptada'';',
'END;'))
,p_process_clob_language=>'PLSQL'
,p_process_when=>'ACEPTAR'
,p_process_when_type=>'REQUEST_EQUALS_CONDITION'
,p_internal_uid=>7876182015316695439
,p_created_on=>wwv_flow_imp.dz('20261026043021Z')
,p_updated_on=>wwv_flow_imp.dz('20261026043021Z')
,p_created_by=>'SIMON.VELASQUEZ'
,p_updated_by=>'SIMON.VELASQUEZ'
);
wwv_flow_imp_page.create_page_process(
 p_id=>wwv_flow_imp.id(7876182169105695440)
,p_process_sequence=>20
,p_process_point=>'BEFORE_HEADER'
,p_process_type=>'NATIVE_PLSQL'
,p_process_name=>'Rechazar solicitud'
,p_static_id=>'rechazar-solicitud'
,p_process_sql_clob=>wwv_flow_string.join(wwv_flow_t_varchar2(
'BEGIN',
'  UPDATE solicitud',
'     SET estado_solicitud = ''RECHAZADA''',
'   WHERE id_solicitud = :P9_ID_SOL',
'     AND UPPER(estado_solicitud) = ''PENDIENTE''',
'     AND id_viaje IN (SELECT id_viaje FROM viaje WHERE id_conductor = :APP_USER);',
'',
'  apex_application.g_print_success_message := ''Solicitud rechazada'';',
'END;'))
,p_process_clob_language=>'PLSQL'
,p_process_when=>'RECHAZAR'
,p_process_when_type=>'REQUEST_EQUALS_CONDITION'
,p_internal_uid=>7876182169105695440
